When server sends state, it should include bullets/asteroids:

```json
{
  "type": "state",
  "bullets": {
    "bullet-1": { "x": 100, "y": 200, "rotation": 1.2 }
  },
  "asteroids": {
    "asteroid-1": { "x": 500, "y": 300, "rotation": 0.4, "variant": 2 }
  }
}
```

Client update pattern:

```gdscript
func apply_bullets(data: Dictionary) -> void:
	for id in data.keys():
		if not bullet_nodes.has(id):
			var bullet = BulletScene.instantiate()
			bullets.add_child(bullet)
			bullet_nodes[id] = bullet

		var bullet = bullet_nodes[id]
		bullet.position = Vector2(data[id]["x"], data[id]["y"])
		bullet.rotation = data[id]["rotation"]
```

Asteroids are same idea, except call your variant method when creating:

```gdscript
func apply_asteroids(data: Dictionary) -> void:
	for id in data.keys():
		if not asteroid_nodes.has(id):
			var asteroid = AsteroidScene.instantiate()
			asteroids.add_child(asteroid)
			asteroid.set_asteroid_variant(data[id]["variant"])
			asteroid_nodes[id] = asteroid

		var asteroid = asteroid_nodes[id]
		asteroid.position = Vector2(data[id]["x"], data[id]["y"])
		asteroid.rotation = data[id]["rotation"]
```

